package com.veyra.finance;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1/finance")@PreAuthorize("hasAnyRole('FINANCE','ADMIN')")public class PartnerInvoiceController{private final JdbcTemplate db;public PartnerInvoiceController(JdbcTemplate d){db=d;}
 @PostMapping("/partners/{partnerId}/invoices/generate")Map<String,Object>generate(@PathVariable UUID partnerId,@RequestParam LocalDate from,@RequestParam LocalDate to){UUID id=UUID.randomUUID();List<Map<String,Object>>items=db.queryForList("select sb.id,bfs.driver_net_amount_minor,bfs.platform_commission_amount_minor,bfs.customer_total_amount_minor,bfs.currency from scheduled_bookings sb join booking_financial_snapshots bfs on bfs.booking_id=sb.id where sb.partner_id=? and sb.payment_method='PARTNER_INVOICE' and sb.status in ('COMPLETED','CLOSED') and sb.scheduled_at::date between ? and ? and not exists(select 1 from partner_invoice_items pii where pii.booking_id=sb.id)",partnerId,from,to);long total=items.stream().mapToLong(x->((Number)x.get("customer_total_amount_minor")).longValue()).sum();db.update("insert into partner_invoices(id,partner_id,period_start,period_end,total_minor,currency,status,due_at) values (?,?,?,?,?,'EUR','ISSUED',?)",id,partnerId,from,to,total,to.plusDays(30));for(var x:items)db.update("insert into partner_invoice_items(invoice_id,booking_id,driver_net_minor,commission_minor,total_minor) values (?,?,?,?,?)",id,x.get("id"),x.get("driver_net_amount_minor"),x.get("platform_commission_amount_minor"),x.get("customer_total_amount_minor"));db.update("update partner_invoice_accounts set outstanding_minor=outstanding_minor+? where partner_id=?",total,partnerId);return Map.of("invoiceId",id,"totalMinor",total,"items",items.size(),"status","ISSUED");}
}